tool_input.command:
$dirs = Get-ChildItem -Directory -Force | Where-Object { $_.Name -notin @('.git','.task-state','openviking-data','data','memory-migration-archive','scripts') }
foreach ($d in $dirs) {
  $files = Get-ChildItem -Recurse -File -Force $d.FullName -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch 'node_modules|\.git' }
  $size = ($files | Measure-Object Length -Sum).Sum
  Write-Output ("{0,-28} files={1,-4} size={2}KB" -f $d.Name, $files.Count, [math]::Round($size/1024,1))
}

function Info($p){
  if(Test-Path $p){
    $f = Get-ChildItem -Path $p -File -Force -ErrorAction SilentlyContinue
    $sub = Get-ChildItem -Path $p -Directory -Force -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Name
    Write-Output ("### {0}" -f $p)
    Write-Output ("  files({0}): {1}" -f $f.Count, (($f | Select-Object -ExpandProperty Name) -join ', '))
    if($sub){ Write-Output ("  subdirs: {0}" -f ($sub -join ', ')) }
  } else { Write-Output "MISSING $p" }
}
$skills = 'agent-cost-hygiene','captcha-recognizer','controller-bench','cursor-model-routing','decision-options','dsh-explore','dsh-token-policy','openviking-autostart','openviking-memory','repo-safety','submodule-commit','tdd','token-frugal','token-optimizer','tool-call-hygiene','vite-build-profiler','web-deploy','worktree-snapshot','zentao-analyzer'
foreach($s in $skills){ Info ".\$s" }
Write-Output "========== DSH =========="
$plugins = 'agent-guard','cost-meter','dcwhc','langgraph-orchestrator','mcp-gateway','orchestrator','orchestrator-gate','plan-gate','token-guard','token-models'
foreach($p in $plugins){ Info ".\dsh\$p" }

$items = 'agent-cost-hygiene','captcha-recognizer','controller-bench','cursor-model-routing','decision-options','dsh-explore','dsh-token-policy','openviking-autostart','repo-safety','submodule-commit','tdd','token-frugal','token-optimizer','tool-call-hygiene','vite-build-profiler','web-deploy','worktree-snapshot','zentao-analyzer','dsh\agent-guard','dsh\cost-meter','dsh\dcwhc','dsh\mcp-gateway','dsh\orchestrator','dsh\orchestrator-gate','dsh\plan-gate','dsh\token-guard','dsh\token-models'
foreach($i in $items){
  $md = Get-ChildItem -Path ".\$i" -Filter *.md -File -ErrorAction SilentlyContinue
  $js = Get-ChildItem -Path ".\$i" -Recurse -Include *.js,*.mjs -File -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch 'node_modules' }
  $py = Get-ChildItem -Path ".\$i" -Recurse -Filter *.py -File -ErrorAction SilentlyContinue
  $ps = Get-ChildItem -Path ".\$i" -Recurse -Filter *.ps1 -File -ErrorAction SilentlyContinue
  $mdl = ($md | Measure-Object Length -Sum).Sum; $jl=($js|Measure-Object Length -Sum).Sum; $pl=($py|Measure-Object Length -Sum).Sum; $sl=($ps|Measure-Object Length -Sum).Sum
  Write-Output ("{0,-24} md={1/-6} js={2/-7} py={3/-5} ps1={4}" -f $i,[int]$mdl,[int]$jl,[int]$pl,[int]$sl)
}

